const $$ = (s,r=document)=>[...r.querySelectorAll(s)];
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',path:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v5a3 3 0 0 0 3 3h6a3 3 0 0 1 3 3M13 5h6m-3-3 3 3-3 3"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m7 9 3 3-3 3m6 0h4"/>',book:'<path d="M12 5v15M3 4c4-1 6-1 9 1 3-2 5-2 9-1v15c-4-1-6-1-9 1-3-2-5-2-9-1Z"/>',layers:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9l-6-6Z"/><path d="M14 3v6h6M8 13h8m-8 4h5"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12c6 4 12 4 18 0m-9 0v4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 1v5m6-5v5M9 18v5m6-5v5M1 9h5m-5 6h5m12-6h5m-5 6h5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',network:'<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="m10 8-4 8m8-8 4 8M8 19h8"/>',grid:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',compare:'<path d="M7 3v18m10-18v18M3 8l4-4 4 4m2 8 4 4 4-4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',note:'<path d="M20 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h7m4-2 6 6-10 10H6v-6L16 2Z"/>'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.book}</svg>`;
const navItems=[['overview','Overview','home'],['path','Learning path','path'],['labs','Hands-on labs','terminal'],['concepts','Concept library','book'],['resources','Resource shelf','layers'],['notes','Research notes','note'],['practice','Practice log','activity'],['portfolio','Portfolio','briefcase']];
const KEY='binary-atlas-v1';
const initial=()=>({schema:1,completions:{},safety:{},notes:[],sessions:[],portfolio:[],bookmarks:[],env:{host:'',guest:'',compiler:'',debugger:'',snapshot:'',c:'Unknown / not assessed',assembly:'Unknown / not assessed'},goal:120});
let state=initial(),storageAvailable=true;
try{const stored=localStorage.getItem(KEY);if(stored)state=validateState(JSON.parse(stored));}catch(e){storageAvailable=false;}
function validateState(x){
 if(!x||x.schema!==1)throw Error('This is not a Binary Atlas v1 backup.');
 const y=initial();
 const str=(s,max=30000)=>typeof s==='string'?s.slice(0,max):'';
 for(const k of ['completions','safety','env'])if(x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k])){
  if(k==='completions')for(const l of LABS){const c=x.completions[l.id];if(c&&typeof c==='object')y.completions[l.id]={date:str(c.date,80),evidence:str(c.evidence)};}
  if(k==='safety')for(const [id] of SAFETY)y.safety[id]=x.safety[id]===true;
  if(k==='env')for(const p of Object.keys(y.env))y.env[p]=str(x.env[p],1000)||y.env[p];
 }
 for(const k of ['notes','sessions','portfolio']){if(x[k]!==undefined&&!Array.isArray(x[k]))throw Error('Invalid '+k+' in backup.');
 y[k]=(x[k]||[]).slice(0,1000).filter(a=>a&&typeof a==='object').map(a=>{
 if(k==='notes')return{id:str(a.id,100),title:str(a.title,300),body:str(a.body),tag:str(a.tag,80),updated:str(a.updated,80)};
 if(k==='sessions')return{id:str(a.id,100),lab:LABS.some(l=>l.id===a.lab)?a.lab:'readiness',minutes:Math.min(1440,Math.max(1,Number(a.minutes)||1)),takeaway:str(a.takeaway,5000),date:str(a.date,80)};
 const p={};for(const z of ['id','title','question','scope','provenance','tools','method','observations','limits','evidence','rerun','date','status'])p[z]=str(a[z]);
 p.status=p.status==='self-verified'&&['title','question','scope','provenance','tools','method','observations','limits','evidence','rerun'].every(z=>p[z].trim())?'self-verified':'draft';return p;
 });}
 y.bookmarks=Array.isArray(x.bookmarks)?x.bookmarks.filter(id=>RESOURCES.some(r=>r.id===id)):[];
 y.goal=Math.min(1200,Math.max(15,Number(x.goal)||120));return y;
}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch(e){storageAvailable=false;toast('Storage unavailable. Export a backup to keep your changes.');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const pretty=d=>{if(!d)return'Not recorded';const v=new Date(d);return isNaN(v)?esc(d):v.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Tokyo'});};
const stage=id=>STAGES.find(s=>s.id===id);
const lab=id=>LABS.find(l=>l.id===id);
const resource=id=>RESOURCES.find(r=>r.id===id);
const done=id=>!!state.completions[id];
const completed=()=>Object.keys(state.completions).length;
const nextLab=()=>LABS.find(l=>!done(l.id))||LABS[0];
const totalMinutes=()=>state.sessions.reduce((s,x)=>s+x.minutes,0);
const weekMinutes=()=>state.sessions.filter(s=>{const t=Date.parse(s.date);return Number.isFinite(t)&&Date.now()-t<7*864e5&&Date.now()-t>=0;}).reduce((s,x)=>s+x.minutes,0);
const tag=(txt,cls='')=>`<span class="tag ${cls}">${esc(txt)}</span>`;
const link=(url,txt,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${txt}</a>`;
let filters={labs:'all',resources:'all',concepts:'All',portfolio:'all'},queries={labs:'',resources:'',concepts:''};
let compareType='resources',compareSelection={resources:['ost2','ce','ghidra'],projects:['p1','p3','p4']};
let traceStep=0,modalReturn=null,modalCloseAction=null;
$('#nav').innerHTML=navItems.map(([id,title,ic],i)=>`${i===5?'<div class="nav-separator">YOUR FIELDWORK</div>':''}<a href="#${id}" data-nav="${id}">${icon(ic)}<span>${title}</span>${id==='path'?'<span class="nav-counter">06</span>':''}</a>`).join('');
$('#search-icon').innerHTML=icon('search');
function heading(eyebrow,title,desc,actions=''){return`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function progressBar(n,d){return`<div class="progress"><span style="width:${d?Math.round(n/d*100):0}%"></span></div>`;}
function stageCard(s){const n=s.labs.filter(done).length;return`<a class="stage-card ${n===s.labs.length?'complete':''}" href="#stage/${s.id}"><div class="stage-top"><span class="stage-number">${s.n}</span><span class="stage-status">${n===s.labs.length?icon('check'):n?'In progress':s.id==='s0'?'Start here':'Explore'}</span></div><h3>${s.title}</h3><p>${s.short}</p><div class="stage-card-footer"><span>${n} / ${s.labs.length} exercises</span>${icon('arrow')}</div>${progressBar(n,s.labs.length)}</a>`;}
function labRow(l){return`<a href="#lab/${l.id}" class="lab-row"><span class="lab-state ${done(l.id)?'done':''}">${done(l.id)?icon('check'):icon('terminal')}</span><span class="lab-row-body"><b>${esc(l.title)}</b><small>${stage(l.stage).n} · ${esc(l.type)}</small></span><span class="lab-time">${l.time} min</span>${icon('arrow')}</a>`;}
function overview(){const n=nextLab(),w=weekMinutes(),verified=state.portfolio.filter(p=>p.status==='self-verified').length;
return`<div class="welcome-line"><span>YOUR RESEARCH, ONE LAYER DEEPER</span><span>${icon('shield')} Educational & defensive</span></div>
<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="green-line"></span>A NEW LENS ON CYBERSECURITY</div><h1>Understand the code.<br><span>Follow the evidence.</span></h1><p>Explore binary analysis and reverse engineering, one small, reproducible investigation at a time.</p><div class="hero-actions"><a class="btn primary" href="#lab/${n.id}">${completed()?'Continue learning':'Begin your learning path'} ${icon('arrow')}</a><a class="hero-secondary" href="#path">Explore the path ↗</a></div><div class="hero-foot"><span class="mini-dot"></span> Built on your cybersecurity & digital forensics experience</div><button class="mobile-trace text-btn" data-action="trace">Try an instruction trace ${icon('arrow')}</button></div><div class="binary-card"><div class="binary-head"><span><span class="tiny-dot"></span> A CLOSER LOOK</span><span>x86-64 / illustrative</span></div><div class="binary-code"><div class="code-label">SOURCE <span>classify.c</span></div><pre><span class="syntax-purple">if</span> (value < <span class="syntax-orange">16</span>)
    <span class="syntax-purple">return</span> <span class="syntax-orange">1</span>;
<span class="syntax-purple">return</span> <span class="syntax-orange">0</span>;</pre><div class="code-divider"><span></span>${icon('arrow')}<span></span></div><div class="code-label">THE INSTRUCTIONS <span>simplified</span></div><div class="assembly-line"><span>01</span><code><b>cmp</b> edi, 0x10</code><i>compare</i></div><div class="assembly-line"><span>02</span><code><b>jae</b> return_zero</code><i>branch</i></div><div class="assembly-line"><span>03</span><code><b>mov</b> eax, 1</code><i>result</i></div></div><button class="trace-link" data-action="trace">Trace the logic ${icon('arrow')}</button></div></section>
<div class="metric-grid"><div class="metric"><span class="metric-icon">${icon('path')}</span><div><span class="metric-value">${completed()}<small> / ${LABS.length}</small></span><span class="metric-label">Exercises completed</span></div><span class="mini-ring" style="--pct:${completed()/LABS.length*100}%"></span></div><div class="metric"><span class="metric-icon amber">${icon('clock')}</span><div><span class="metric-value">${totalMinutes()}<small> min</small></span><span class="metric-label">Intentional practice</span></div><a href="#practice" aria-label="Open practice log">↗</a></div><div class="metric"><span class="metric-icon blue">${icon('briefcase')}</span><div><span class="metric-value">${verified}<small> projects</small></span><span class="metric-label">Self-verified findings</span></div><a href="#portfolio" aria-label="Open portfolio">↗</a></div></div>
<div class="overview-columns"><div><div class="section-title"><div><h2>Your learning path</h2><p>A foundation first. Then room to explore.</p></div><a href="#path">View full path ${icon('arrow')}</a></div><div class="stage-grid overview-stages">${STAGES.slice(0,3).map(stageCard).join('')}</div><section class="panel next-panel"><div class="section-title compact"><h2>On your workbench</h2><a href="#labs">All exercises ↗</a></div>${labRow(n)}${labRow(LABS[(LABS.indexOf(n)+1)%LABS.length])}</section><section class="bridge-banner"><span class="bridge-symbol">${icon('network')}</span><div><h3>You’re extending a strong foundation.</h3><p>Python, Windows logs, Security Onion, Neo4j, digital forensics, and identity security all have a place in this next chapter.</p><button class="text-btn" data-action="profile">See the connections ${icon('arrow')}</button></div></section></div>
<aside class="overview-rail"><section class="panel weekly"><div class="section-title compact"><h2>A little, consistently.</h2>${icon('activity')}</div><p>Your last 7 days of practice</p><div class="weekly-value">${w}<span> / ${state.goal} min</span></div>${progressBar(Math.min(w,state.goal),state.goal)}<div class="weekly-caption">${w>=state.goal?'Your practice goal is reached. Capture what you learned.':'A suggested rhythm, never a deadline.'}</div><button class="btn secondary full" data-action="session">${icon('plus')} Log a session</button></section><section class="panel lab-ready"><span class="small-icon">${icon('shield')}</span><h3>Make room for safe curiosity.</h3><p>Isolated VM. Benign programs.<br>A clean snapshot to return to.</p><a href="#lab-setup">Set up your lab ${icon('arrow')}</a><span class="checklist-count">${SAFETY.filter(([id])=>state.safety[id]).length} of ${SAFETY.length} checks recorded</span></section><button class="quick-note" data-action="note-new"><span>${icon('note')} A question worth keeping?</span><b>Add a research note ${icon('plus')}</b></button></aside></div>`;}
function pathView(){return heading('THE LEARNING PATH','Go deeper, one layer at a time.','Six stages. Evidence-based milestones. Move at your own pace.',`<a class="btn secondary" href="#compare">${icon('compare')} Compare projects</a>`)+`<div class="info-strip">${icon('target')} <span>C confidence: <b>${esc(state.env.c)}</b>. Assembly: <b>${esc(state.env.assembly)}</b>. Begin with the baseline and revisit stages whenever useful.</span></div><div class="stage-grid full-path">${STAGES.map(stageCard).join('')}</div><section class="panel path-principles"><div><span class="eyebrow">HOW TO USE THIS PATH</span><h2>Learn → observe → explain → verify</h2><p>Each stage has a small output and an evidence gate. Exercise completion is your own record, not a certification or an independent skills assessment.</p></div><div><h3>Choose depth over speed</h3><p>Lab times are planning estimates. Keep a question log, revisit assumptions, and move on when you can explain your evidence.</p><a href="#lab-setup" class="text-link">Prepare the environment ${icon('arrow')}</a></div></section>`;}
function stageView(id){const s=stage(id);if(!s)return notFound();return heading('STAGE '+s.n,s.title,s.desc,`<a class="btn secondary" href="#path">← All stages</a>`)+`<div class="detail-grid"><div class="panel padded"><div class="eyebrow">YOUR INVESTIGATIONS</div>${s.labs.map(id=>labRow(lab(id))).join('')}<div class="section-title"><h2>Concepts to keep close</h2></div><div class="tags">${s.topics.map(t=>tag(t)).join('')}</div><div class="callout"><b>Evidence gate</b><p>${esc(s.gate)}</p></div></div><aside><section class="panel padded"><span class="small-icon">${icon('network')}</span><h3>Connect what you know</h3><p>${esc(s.bridge)}</p></section><section class="panel padded spaced"><h3>Relevant resources</h3>${RESOURCES.filter(r=>r.stage===s.id).map(r=>`<a class="simple-row" href="#resource/${r.id}">${icon(r.icon)}<span>${r.name}</span>↗</a>`).join('')||'<a class="text-link" href="#resources">Browse the resource shelf ↗</a>'}</section></aside></div>`;}
function labsView(){const list=LABS.filter(l=>(filters.labs==='all'||filters.labs==='done'&&done(l.id)||filters.labs==='todo'&&!done(l.id)||l.stage===filters.labs)&&(l.title+' '+l.type+' '+l.objective).toLowerCase().includes(queries.labs));return heading('HANDS-ON LABS','A workbench for your curiosity.','Small, controlled exercises. Real observations. A record you can reproduce.',`<a href="#lab-setup" class="btn secondary">${icon('shield')} Lab setup</a>`)+`<div class="toolbar"><div class="tabs"><button data-filter="labs" data-value="all" class="${filters.labs==='all'?'active':''}">All exercises <span>${LABS.length}</span></button><button data-filter="labs" data-value="todo" class="${filters.labs==='todo'?'active':''}">To explore</button><button data-filter="labs" data-value="done" class="${filters.labs==='done'?'active':''}">Completed</button></div><label class="inline-search">${icon('search')}<input data-query="labs" placeholder="Find an exercise…" value="${esc(queries.labs)}" aria-label="Find an exercise"></label></div><div class="exercise-grid">${list.map(l=>`<a class="exercise-card" href="#lab/${l.id}"><div class="card-top"><span class="tile-icon">${icon(l.type==='Reflection'?'note':'terminal')}</span>${tag(done(l.id)?'Completed':l.level,done(l.id)?'green':'')}</div><span class="eyebrow">STAGE ${stage(l.stage).n} · ${esc(l.type)}</span><h3>${esc(l.title)}</h3><p>${esc(l.objective)}</p><div class="card-footer"><span>${icon('clock')} ${l.time} min estimate</span>${icon('arrow')}</div></a>`).join('')||empty('No exercises match','Try another search or filter.','Show all exercises','clear-labs')}</div>`;}
function labView(id){const l=lab(id);if(!l)return notFound();const s=stage(l.stage),e=state.completions[id];return heading('STAGE '+s.n+' / '+l.type,l.title,l.objective,`<a class="btn secondary" href="#labs">← Exercises</a><button class="btn ${e?'secondary':'primary'}" data-action="lab-complete" data-id="${id}">${icon(e?'check':'plus')}${e?'View completion':'Record completion'}</button>`)+`<div class="tags lab-tags">${tag(l.level)}${tag(l.time+' min · estimate')}${tag('Owned / authorized programs','green')}</div><div class="detail-grid"><div><section class="panel padded"><div class="section-title compact"><h2>The investigation</h2></div><ol class="step-list">${l.steps.map(t=>`<li><p>${esc(t)}</p></li>`).join('')}</ol>${l.commands?`<div class="code-toolbar"><span>LAB COMMANDS · RUN IN YOUR VM</span><button class="text-btn" data-action="copy-commands" data-id="${l.id}">Copy commands</button></div><pre class="code-block">${esc(l.commands)}</pre>`:''}${l.source?`<details class="source-details"><summary>Inspect the supplied teaching source <span>＋</span></summary><pre class="code-block">${esc(l.source)}</pre><button class="btn secondary" data-action="source" data-id="${l.id}">${icon('download')} Download ${esc(l.filename)}</button></details>`:''}<div class="callout"><b>Expected learning output</b><p>${esc(l.outcome)}</p><small>This describes the intended artifact. It is not a pre-recorded result.</small></div></section><section class="panel padded spaced"><h2>Keep the context</h2><p>${esc(s.bridge)}</p><div class="button-row"><button class="btn secondary" data-action="note-lab" data-id="${l.id}">${icon('note')} Take a lab note</button><button class="btn secondary" data-action="handout" data-id="${l.id}">${icon('download')} Download guide</button></div></section></div><aside><section class="panel padded"><h3>Evidence to preserve</h3><ul class="evidence-list">${l.evidence.map(t=>`<li>${icon('file')}<span>${esc(t)}</span></li>`).join('')}</ul><button class="btn secondary full" data-action="session" data-id="${id}">${icon('clock')} Log practice time</button></section><section class="panel padded spaced"><div class="eyebrow">READ ALONG</div><h3>${resource(l.resource).name}</h3><p>${esc(resource(l.resource).fit)}</p><a class="text-link" href="#resource/${l.resource}">Resource details ↗</a></section>${e?`<div class="callout completion"><b>Completion recorded</b><p>${pretty(e.date)}</p><p>${esc(e.evidence)}</p><small>Self-reported learning progress.</small></div>`:''}</aside></div>`;}
function setupView(){const count=SAFETY.filter(([id])=>state.safety[id]).length;return heading('SAFE LAB SETUP','Create a place to explore.','A recoverable, isolated environment for benign and explicitly authorized learning.',`<button class="btn secondary" data-action="environment">${icon('cpu')} Record environment</button>`)+`<div class="detail-grid"><section class="panel padded"><div class="section-title"><h2>Your lab checklist</h2><span class="muted">${count} / ${SAFETY.length} recorded</span></div>${progressBar(count,SAFETY.length)}<div class="safety-list">${SAFETY.map(([id,title,desc])=>`<label class="safety-item"><input type="checkbox" data-safety="${id}" ${state.safety[id]?'checked':''}><span><b>${esc(title)}</b><p>${esc(desc)}</p></span></label>`).join('')}</div><div class="small-note">These checks are your own record; the workspace cannot inspect or verify your VM configuration.</div></section><aside><section class="panel padded"><span class="small-icon">${icon('cpu')}</span><h3>Your environment</h3><dl class="env-list">${[['host','Host / architecture'],['guest','Guest OS'],['compiler','Compiler'],['debugger','Debugger'],['snapshot','Clean snapshot']].map(([k,t])=>`<div><dt>${t}</dt><dd>${esc(state.env[k]||'Not recorded')}</dd></div>`).join('')}</dl><button class="btn secondary full" data-action="environment">Update baseline</button></section><section class="panel padded spaced"><h3>A simple starting stack</h3><p>Linux x86-64 VM · C compiler · GDB · Ghidra. Add a Windows VM later for PE and telemetry work.</p><p>Hardware capacity, host architecture, installed versions, and licenses are not assumed. Check the official requirements before installing.</p><a href="#resources" class="text-link">Official resources ${icon('arrow')}</a></section></aside></div>`;}
function conceptsView(){const cats=['All','Foundations','Machine code','Analysis','Research'];const rows=CONCEPTS.filter(c=>(filters.concepts==='All'||filters.concepts===c.category)&&(c.title+' '+c.desc).toLowerCase().includes(queries.concepts));return heading('CONCEPT LIBRARY','Build a useful mental model.','Short explanations to revisit before, during, and after your investigations.')+`<div class="toolbar"><div class="tabs wrap">${cats.map(c=>`<button data-filter="concepts" data-value="${c}" class="${filters.concepts===c?'active':''}">${c}</button>`).join('')}</div><label class="inline-search">${icon('search')}<input data-query="concepts" placeholder="Find a concept…" aria-label="Find a concept" value="${esc(queries.concepts)}"></label></div><div class="concept-grid">${rows.map((c,i)=>`<button class="concept-card" data-action="concept" data-id="${c.id}"><span class="concept-index">${String(CONCEPTS.indexOf(c)+1).padStart(2,'0')}</span><span class="eyebrow">${c.category}</span><h3>${c.title}</h3><p>${c.desc}</p><span class="text-link">Explore concept ${icon('arrow')}</span></button>`).join('')||empty('No matching concepts','Try a broader search.','Clear filters','clear-concepts')}</div>`;}
function resourcesView(){const kinds=['all','Structured course','Interactive tool','Analysis tool','Reference','Defensive tool','Practice platform'];const rows=RESOURCES.filter(r=>(filters.resources==='all'||filters.resources==='saved'&&state.bookmarks.includes(r.id)||r.kind===filters.resources)&&(r.name+' '+r.subtitle+' '+r.prereq).toLowerCase().includes(queries.resources));return heading('THE RESOURCE SHELF','Good sources. Clear tradeoffs.','A small, curated shelf of primary sources, tools, and authorized practice.',`<a class="btn primary" href="#compare/resources">${icon('compare')} Compare resources</a>`)+`<div class="info-strip">${icon('book')}<span>Official pages checked <b>11 November 2026</b>. Descriptions are curated guidance; study time and fit are estimates. Current versions and access terms may change.</span></div><div class="toolbar"><div class="filter-select"><label for="resource-kind">Type</label><select id="resource-kind" data-select-filter="resources">${kinds.map(k=>`<option value="${k}" ${filters.resources===k?'selected':''}>${k==='all'?'All resources':k}</option>`).join('')}<option value="saved" ${filters.resources==='saved'?'selected':''}>Saved resources</option></select></div><label class="inline-search">${icon('search')}<input data-query="resources" placeholder="Find a resource…" aria-label="Find a resource" value="${esc(queries.resources)}"></label></div><div class="resource-grid">${rows.map(r=>`<article class="resource-card"><div class="card-top"><span class="tile-icon">${icon(r.icon)}</span><button class="save-resource ${state.bookmarks.includes(r.id)?'saved':''}" data-action="bookmark" data-id="${r.id}" title="${state.bookmarks.includes(r.id)?'Unsave':'Save'} resource" aria-label="${state.bookmarks.includes(r.id)?'Unsave':'Save'} ${esc(r.name)}">${state.bookmarks.includes(r.id)?'★':'☆'}</button></div><span class="eyebrow">${r.kind} · STAGE ${stage(r.stage).n}</span><h3><a href="#resource/${r.id}">${r.name}</a></h3><span class="resource-subtitle">${r.subtitle}</span><p>${r.fit}</p><div class="resource-meta"><span>PREREQUISITE</span><b>${r.prereq}</b></div><div class="card-footer"><span>${r.cost}</span><a class="text-link" href="#resource/${r.id}">Details ↗</a></div></article>`).join('')||empty('Nothing on this shelf yet','Try another filter or save resources with the star.','Show all resources','clear-resources')}</div>`;}
function resourceView(id){const r=resource(id);if(!r)return notFound();return heading(r.kind,r.name,r.subtitle,`<a href="#resources" class="btn secondary">← Resource shelf</a>${link(r.url,'Open official resource ↗','btn primary')}`)+`<div class="detail-grid"><section class="panel padded"><h2>Why it belongs on your shelf</h2><p>${r.fit}</p><div class="callout"><b>Tradeoff to understand</b><p>${r.tradeoff}</p></div><dl class="resource-facts">${[['Recommended stage',stage(r.stage).title],['Prerequisites',r.prereq],['Level',r.level],['Access / cost',r.cost],['Time',r.duration],['Source',r.source],['Page checked','11 November 2026']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="small-note">The stage and suitability are editorial recommendations. This page does not track course completion or guarantee current pricing, compatibility, or availability. Verify requirements on the official page.</p></section><aside><section class="panel padded"><h3>Use it in practice</h3>${LABS.filter(l=>l.resource===id).map(labRow).join('')||'<p>Use this as an optional supplement once your foundations are comfortable.</p>'}<button class="btn secondary full" data-action="bookmark" data-id="${id}">${state.bookmarks.includes(id)?'★ Saved to your shelf':'☆ Save to your shelf'}</button></section></aside></div>`;}
function compareView(type){compareType=type==='projects'?'projects':'resources';const proj=compareType==='projects',items=proj?PROJECTS:RESOURCES,selected=items.filter(r=>compareSelection[compareType].includes(r.id));const fields=proj?[['Learning goal','desc'],['Level','level'],['Planning estimate','effort'],['Tools','tools'],['Your experience bridge','bridge'],['Concrete deliverable','deliverable'],['Limits to preserve','limits']]:[['Best use','fit'],['Format','kind'],['Level','level'],['Prerequisites','prereq'],['Access / cost','cost'],['Study time','duration'],['Tradeoff','tradeoff'],['Source','source']];return heading('COMPARE & CHOOSE','Find the right next step.','Compare fit and effort. Keep uncertainty visible.',`<a class="btn secondary" href="#${proj?'portfolio':'resources'}">← ${proj?'Portfolio':'Resources'}</a>`)+`<div class="tabs compare-tabs"><a href="#compare/resources" class="${!proj?'active':''}">${icon('book')} Learning resources</a><a href="#compare/projects" class="${proj?'active':''}">${icon('briefcase')} Project ideas</a></div><div class="compare-select panel"><b>Choose up to 3</b><div class="compare-chips">${items.map(r=>`<label class="compare-chip ${compareSelection[compareType].includes(r.id)?'selected':''}"><input type="checkbox" data-compare="${r.id}" ${compareSelection[compareType].includes(r.id)?'checked':''}><span>${esc(r.name||r.title)}</span></label>`).join('')}</div></div>${selected.length?`<div class="table-scroll"><table class="compare-table"><thead><tr><th scope="col">${proj?'PROJECT FIT':'RESOURCE FIT'}</th>${selected.map(r=>`<th scope="col"><span class="tile-icon">${icon(r.icon)}</span><h3>${esc(r.name||r.title)}</h3>${tag(proj?'Idea · not completed':stage(r.stage).title)}${proj?`<button class="text-btn" data-action="project-start" data-id="${r.id}">Create a draft ${icon('arrow')}</button>`:link(r.url,'Official source ↗','text-link')}</th>`).join('')}</tr></thead><tbody>${fields.map(([k,f])=>`<tr><th scope="row">${k}</th>${selected.map(r=>`<td>${esc(r[f])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Choose something to compare','Select one, two, or three items above.')}<p class="small-note">${proj?'All listed projects are suggestions. None is recorded as an existing achievement. Session counts are planning estimates.':'Source pages checked 11 November 2026. Unverified duration and access details are labeled rather than inferred.'}</p>`;}
function empty(title,desc,button,action){return`<div class="empty-state"><span class="empty-icon">${icon('note')}</span><h3>${title}</h3><p>${desc}</p>${button?`<button class="btn secondary" data-action="${action}">${button}</button>`:''}</div>`;}
function notesView(){return heading('RESEARCH NOTES','Keep the question. Keep the context.','Your observations, open questions, and next experiments.',`<button class="btn primary" data-action="note-new">${icon('plus')} New note</button>`)+`<div class="notes-intro"><button data-action="note-template" data-id="lab">${icon('terminal')} Lab note <span>Sample · method · observation</span>＋</button><button data-action="note-template" data-id="question">${icon('book')} Open question <span>What would change your mind?</span>＋</button><button data-action="note-template" data-id="report">${icon('file')} Finding outline <span>Evidence · scope · limitations</span>＋</button></div><div class="section-title"><h2>Your notebook</h2><span class="muted">${state.notes.length} notes</span></div>${state.notes.length?`<div class="note-grid">${[...state.notes].sort((a,b)=>b.updated.localeCompare(a.updated)).map(n=>`<button class="note-card" data-action="note-edit" data-id="${esc(n.id)}">${tag(n.tag||'Research')}<h3>${esc(n.title||'Untitled note')}</h3><p>${esc(n.body.slice(0,190))}${n.body.length>190?'…':''}</p><div>${pretty(n.updated)} <span>Open note ↗</span></div></button>`).join('')}</div>`:empty('Every investigation starts with a question.','Save your first observation, a lab baseline, or something you still need to understand.','Write your first note','note-new')}`;}
function practiceView(){const mins=totalMinutes(),w=weekMinutes();return heading('PRACTICE LOG','Track the practice, not just the hours.','Record the work you did and the one thing you learned.',`<button class="btn primary" data-action="session">${icon('plus')} Log a session</button>`)+`<div class="metric-grid"><div class="metric"><span class="metric-icon">${icon('clock')}</span><div><span class="metric-value">${mins}<small> min</small></span><span class="metric-label">Total logged practice</span></div></div><div class="metric"><span class="metric-icon amber">${icon('activity')}</span><div><span class="metric-value">${state.sessions.length}<small> sessions</small></span><span class="metric-label">Learning moments recorded</span></div></div><div class="metric"><span class="metric-icon blue">${icon('target')}</span><div><span class="metric-value">${w}<small> / ${state.goal} min</small></span><span class="metric-label">Last 7 days · editable goal</span></div><button class="text-btn" data-action="settings">Edit ↗</button></div></div><section class="panel padded"><div class="section-title"><h2>Your fieldwork</h2><span class="muted">Times are self-reported</span></div>${state.sessions.length?`<div class="table-scroll"><table class="log-table"><thead><tr><th>Date</th><th>Investigation & takeaway</th><th>Time</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${[...state.sessions].reverse().map(s=>`<tr><td>${pretty(s.date)}</td><td><a href="#lab/${s.lab}"><b>${esc(lab(s.lab)?.title||'Learning session')}</b></a><p>${esc(s.takeaway)}</p></td><td>${s.minutes} min</td><td><button class="text-btn danger" data-action="session-delete" data-id="${esc(s.id)}" aria-label="Delete session from ${pretty(s.date)}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:empty('Small sessions add up.','After your next exercise, record the time and a concrete takeaway.','Log a learning session','session')}</section>`;}
function publishedPortfolio(){
 const entries=typeof PUBLISHED_PROJECTS==='undefined'?[]:PUBLISHED_PROJECTS;
 const cards=entries.map(p=>'<article class="portfolio-card"><div class="card-top">'+tag(p.status==='self-verified'?'Self-verified':'In progress',p.status==='self-verified'?'green':'')+'</div><h3>'+esc(p.title)+'</h3><p>'+esc(p.question)+'</p><p class="small-note">'+esc(p.limits||'Conclusions remain in progress; consult the report for current limits.')+'</p><a class="btn secondary" href="portfolio/'+esc(p.report)+'" target="_blank" rel="noopener noreferrer">Read report (.md) ↗</a></article>').join('');
 return '<section class="panel padded"><div class="section-title"><div><div class="eyebrow">COMMITTED TO GITHUB</div><h2>Published investigations</h2><p>Reviewed reports shared from the repository. Verification records the author’s own attestation.</p></div><a href="https://github.com/Conqueror226/binary-atlas" target="_blank" rel="noopener noreferrer">Repository ↗</a></div>'+(entries.length?'<div class="project-grid">'+cards+'</div>':'<p>No investigations have been published yet. Start with the guided labs; completed research will appear here after review and a Git commit.</p>')+'</section><div class="section-title"><div><h2>Your browser workspace</h2><p>Local drafts and practice records stay in this browser. To publish a report, export its Markdown and commit the reviewed content to GitHub.</p></div></div>';
}
function portfolioView(){const list=state.portfolio.filter(p=>filters.portfolio==='all'||p.status===filters.portfolio);return heading('THE EVIDENCE PORTFOLIO','Let the work speak clearly.','Document completed investigations with reproducible evidence and honest limits.',`<a class="btn secondary" href="#compare/projects">${icon('compare')} Compare ideas</a><button class="btn primary" data-action="portfolio-new">${icon('plus')} New project</button>`)+publishedPortfolio()+`<div class="info-strip">${icon('shield')}<span><b>Draft → evidence → clean rerun → self-verified.</b> Verification is your attestation. No projects, findings, or credentials have been assumed.</span></div><div class="toolbar"><div class="tabs">${[['all','All projects'],['draft','Drafts'],['self-verified','Self-verified']].map(([v,t])=>`<button data-filter="portfolio" data-value="${v}" class="${filters.portfolio===v?'active':''}">${t}</button>`).join('')}</div><span class="muted">${list.length} entries</span></div>${list.length?`<div class="project-grid">${list.map(p=>`<article class="portfolio-card"><div class="card-top"><span class="tile-icon">${icon('briefcase')}</span>${tag(p.status==='self-verified'?'Self-verified':'Draft',p.status==='self-verified'?'green':'')}</div><h3>${esc(p.title)}</h3><p>${esc(p.question||'Research question not recorded.')}</p><div class="small-note">${p.status==='self-verified'?'Rerun attested · '+pretty(p.date):'Evidence and verification are in progress.'}</div><div class="button-row"><button class="btn secondary" data-action="portfolio-edit" data-id="${esc(p.id)}">Open report ↗</button><button class="text-btn" data-action="portfolio-export" data-id="${esc(p.id)}">Export .md</button></div></article>`).join('')}</div>`:empty(filters.portfolio==='all'?'Your first finding belongs here.':'No '+(filters.portfolio==='draft'?'drafts':'self-verified projects')+' yet.','A good portfolio begins with a small claim you can reproduce.','Create a project draft','portfolio-new')}<div class="section-title ideas-title"><div><h2>Ideas that connect to your experience</h2><p>Suggested investigations, ready when you are.</p></div><a href="#compare/projects">Compare ideas ${icon('arrow')}</a></div><div class="project-grid">${PROJECTS.map(p=>`<article class="project-idea"><div class="card-top"><span class="tile-icon">${icon(p.icon)}</span>${tag('Project idea')}</div><h3>${p.title}</h3><p>${p.desc}</p><small>${p.level} · ${p.effort}</small><button class="text-btn" data-action="project-start" data-id="${p.id}">Start a draft ${icon('arrow')}</button></article>`).join('')}</div>`;}
function notFound(){return heading('WORKSPACE','This page is not on the map.','Return to the overview to continue your exploration.',`<a class="btn primary" href="#overview">Overview ${icon('arrow')}</a>`);}
function render(){const [rawRoute,id]=location.hash.slice(1).split('/');const route=rawRoute||'overview';let out;const names={...Object.fromEntries(navItems.map(x=>[x[0],x[1]])),'lab-setup':'Lab setup',stage:'Learning path',lab:'Hands-on labs',resource:'Resource shelf',compare:'Compare & choose'};
 switch(route){case'overview':out=overview();break;case'path':out=pathView();break;case'stage':out=stageView(id);break;case'labs':out=labsView();break;case'lab':out=labView(id);break;case'lab-setup':out=setupView();break;case'concepts':out=conceptsView();break;case'resources':out=resourcesView();break;case'resource':out=resourceView(id);break;case'compare':out=compareView(id);break;case'notes':out=notesView();break;case'practice':out=practiceView();break;case'portfolio':out=portfolioView();break;default:out=notFound();}
 $('#main').innerHTML=out;$('#crumb-title').textContent=names[route]||'Workspace';document.title=(names[route]||'Workspace')+' · Binary Atlas';
 $$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(route==='stage'?'path':route==='lab'||route==='lab-setup'?'labs':route==='resource'||route==='compare'?'resources':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(!storageAvailable)$('#main').insertAdjacentHTML('afterbegin','<div class="info-strip">Browser storage could not be read. Use Manage & export to preserve changes.</div>');
}
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('.mobile-menu').setAttribute('aria-expanded',String(open));$('#sidebar').inert=window.matchMedia('(max-width:760px)').matches&&!open;}
window.matchMedia('(max-width:760px)').addEventListener('change',()=>setMenu(false));
setMenu(false);
function navigate(){closeModal();render();setMenu(false);window.scrollTo({top:0});}
window.addEventListener('hashchange',navigate);
function showModal(title,body,wide=false){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span class="eyebrow">BINARY ATLAS / WORKSPACE</span><h2 id="modal-title">${esc(title)}</h2></div><button class="icon-btn close-modal" data-action="close" aria-label="Close dialog">×</button></header><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('.modal input,.modal textarea,.modal select,.modal button')?.focus(),20);}
function closeModal(){if(!$('#modal-root').innerHTML)return;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');if(modalCloseAction){modalCloseAction();modalCloseAction=null;}if(modalReturn?.isConnected)modalReturn.focus();}
function field(name,label,value='',opts={}){const {type='text',required=false,placeholder='',rows=4}=opts;return`<label class="form-field"><span>${label}${required?' <i>*</i>':''}</span>${type==='textarea'?`<textarea name="${name}" rows="${rows}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}" ${type==='number'?'min="1" max="1440"':''}>`}</label>`;}
function formFooter(primary='Save',extra=''){return`<div class="form-footer">${extra}<button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn primary" type="submit">${primary} ${icon('check')}</button></div>`;}
const noteTemplates={lab:'Question\n\nScope & source provenance\n\nEnvironment, hashes & tool versions\n\nMethod & inputs\n\nObservations (what I saw)\n\nInterpretation & alternative explanations\n\nLimitations & open questions\n\nNext experiment\n',question:'Question\n\nWhy it matters\n\nCurrent hypothesis\n\nWhat evidence would support or refute it?\n\nOfficial sources to check\n\nNext action\n',report:'Research question\n\nScope & authorization\n\nSample provenance and SHA-256\n\nEnvironment, versions, and build flags\n\nReproduction steps\n\nObservations and evidence references\n\nInterpretation and alternative explanations\n\nLimitations\n\nClean rerun result\n'};
function noteEditor(id,template,labId){const n=state.notes.find(n=>n.id===id);const l=lab(labId);showModal(n?'Edit research note':'A question worth keeping',`<form id="note-form" data-id="${esc(id||'')}">${field('title','Note title',n?.title||(l?l.title:''),{required:true,placeholder:'What are you investigating?'})}<label class="form-field"><span>Category</span><select name="tag">${['Research','Lab note','Open question','Finding'].map(t=>`<option ${t===(n?.tag||(l?'Lab note':template==='question'?'Open question':template==='report'?'Finding':'Research'))?'selected':''}>${t}</option>`).join('')}</select></label>${field('body','Notes',n?.body||(template?noteTemplates[template]:l?noteTemplates.lab:''),{type:'textarea',rows:14,placeholder:'Separate what you observed from what you think it means.'})}<p class="small-note">Saved as plain text in this browser. Export a backup to keep a portable copy.</p>${formFooter('Save note',n?`<button type="button" class="text-btn danger" data-action="note-delete" data-id="${esc(id)}">Delete note</button>`:'')}</form>`,true);}
function sessionEditor(labId){showModal('Record a learning session',`<form id="session-form"><label class="form-field"><span>Investigation</span><select name="lab">${LABS.map(l=>`<option value="${l.id}" ${l.id===(labId||nextLab().id)?'selected':''}>${l.title}</option>`).join('')}</select></label><div class="form-grid">${field('minutes','Time practiced (minutes)','',{type:'number',required:true,placeholder:'e.g. 35'})}${field('date','Date',today(),{type:'date',required:true})}</div>${field('takeaway','What did you learn?','',{type:'textarea',required:true,placeholder:'One concrete observation, a resolved question, or your next step.'})}${formFooter('Save session')}</form>`);}
const portfolioFields=[['question','Research question'],['scope','Scope & authorization'],['provenance','Sample provenance, source & SHA-256'],['tools','Environment, tool versions & build flags'],['method','Reproduction steps & inputs'],['observations','Observations & bounded conclusions'],['evidence','Evidence references'],['limits','Limitations & alternative explanations'],['rerun','Clean rerun result & date']];
function portfolioEditor(id,projectId){const p=state.portfolio.find(p=>p.id===id);const idea=PROJECTS.find(p=>p.id===projectId);showModal(p?'Project report':'Start an evidence-led project',`<form id="portfolio-form" data-id="${esc(id||'')}"><p class="form-intro">Unknown details can stay blank in a draft. A self-verified entry requires every evidence field and your explicit rerun attestation.</p>${field('title','Project title',p?.title||idea?.title||'',{required:true,placeholder:'A small, verifiable investigation'})}${portfolioFields.map(([k,t])=>field(k,t,p?.[k]||'',{type:'textarea',rows:k==='method'||k==='observations'?4:2,placeholder:k==='scope'?'Owned toy program or explicitly authorized target; boundaries of this investigation':k==='provenance'?'Record actual hashes and sources; leave unknown values blank':k==='evidence'?'Local artifact paths or report references. Only cite evidence that exists.':k==='rerun'?'Date, clean environment, exact steps repeated, and observed result':'Not recorded yet'})).join('')}<div class="verification-box"><label><input type="checkbox" name="verified" ${p?.status==='self-verified'?'checked':''}><span><b>Mark as self-verified</b><small>I have checked the referenced evidence and repeated the method in a clean environment. This records my own attestation.</small></span></label></div><p class="form-error" id="portfolio-error" role="alert"></p>${formFooter('Save project',p?`<button class="text-btn danger" type="button" data-action="portfolio-delete" data-id="${esc(id)}">Delete draft / report</button>`:'')}</form>`,true);}
function completionModal(id){const l=lab(id);if(!l)return;const c=state.completions[id];showModal(c?'Completion record':'Record your learning output',c?`<p><b>${esc(l.title)}</b></p><p>Recorded ${pretty(c.date)}</p><div class="callout"><b>Evidence reference</b><p>${esc(c.evidence)}</p></div><p class="small-note">This is self-reported progress. The workspace has not inspected the evidence.</p><div class="form-footer"><button class="text-btn danger" data-action="completion-remove" data-id="${id}">Mark as still exploring</button><button class="btn primary" data-action="close">Done</button></div>`:`<form id="completion-form" data-id="${id}"><p>Complete <b>${esc(l.title)}</b> when you have produced the learning output and preserved these items:</p><div class="completion-checks">${l.evidence.map((e,i)=>`<label><input type="checkbox" required name="ev${i}"><span>${esc(e)}</span></label>`).join('')}</div>${field('evidence','Where is your evidence?','',{type:'textarea',required:true,placeholder:'A note title, local artifact path, or report reference. Do not invent a result.'})}<p class="small-note">This is your own completion record. It does not independently verify proficiency or findings.</p>${formFooter('Record completion')}</form>`);}
function environmentEditor(){showModal('Record your environment',`<form id="environment-form"><p class="form-intro">Leave unknown details blank. Values here describe your lab; they do not configure or inspect it.</p>${[['host','Host OS & CPU architecture'],['guest','Guest OS & architecture'],['compiler','Compiler & version'],['debugger','Debugger & version'],['snapshot','Clean snapshot name & date']].map(([k,t])=>field(k,t,state.env[k],{placeholder:'Not recorded'})).join('')}<div class="form-grid">${['c','assembly'].map(k=>`<label class="form-field"><span>${k==='c'?'C programming':'Assembly'} confidence</span><select name="${k}">${['Unknown / not assessed','Not tried','Learning','Independently practiced'].map(t=>`<option ${state.env[k]===t?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}</div>${formFooter('Save baseline')}</form>`);}
function profileModal(){const links=[['Python','Automate hashes, byte inspection, build manifests, and repeatable experiments.'],['Windows event logs','Connect logon and process context to observed behavior; preserve audit configuration and event provenance.'],['Security Onion','Compare observations with telemetry actually collected in your isolated lab. Coverage is not assumed.'],['Neo4j','Model functions, samples, hypotheses, and observations with traceable evidence relationships.'],['Digital forensics','Preserve provenance, timelines, alternative explanations, and reproducibility.'],['Identity security','Bring contextual reasoning to program behavior without equating identity reachability with code exploitability.']];showModal('Your background is a bridge',`<div class="profile-intro"><span class="avatar large">KB</span><div><h3>A. Kader BONZI</h3><p>Cybersecurity → low-level research exploration</p></div></div><p>Your existing background is the starting point. It does not imply prior proficiency in C, assembly, reverse engineering, or vulnerability research.</p><div class="bridge-list">${links.map(([t,d])=>`<div><span class="small-icon">${icon('arrow')}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><div class="callout"><b>Still to discover</b><p>Preferred OS, host capacity, C and assembly proficiency, exact tool versions, weekly availability, and future research focus.</p></div><div class="form-footer"><button class="btn secondary" data-action="environment">Record a baseline</button><button class="btn primary" data-action="close">Back to exploring</button></div>`,true);}
function settingsModal(){showModal('Your workspace, your record',`<form id="settings-form"><p class="form-intro">Notes, progress, lab checks, and project reports are saved in this browser on this device. They do not sync between devices or become GitHub commits. To move from the original site, export there and import the JSON here. Export regularly; clearing browser data can remove them.</p>${field('goal','Practice goal for 7 days (minutes)',state.goal,{type:'number',required:true})}${formFooter('Save goal')}</form><hr><h3>Keep a portable copy</h3><p class="muted">GitHub stores learning materials and committed portfolio reports. Use JSON backups for personal notes and progress, and reviewed Markdown reports for publication.</p><p class="muted">Export a JSON backup of your workspace. Importing lets you review the backup before replacing the current record.</p><div class="button-row"><button class="btn secondary" data-action="export">${icon('download')} Export workspace</button><label class="btn secondary import-label">Import backup<input type="file" id="import-file" accept="application/json,.json"></label></div><p class="small-note">No browser-based compiler or debugger is connected. Run the supplied source in your own lab. Resources are links to external official sites.</p>`);}
function conceptModal(id){const c=CONCEPTS.find(c=>c.id===id);if(!c)return;showModal(c.title,`${tag(c.category)}<p class="lead-copy">${c.desc}</p><div class="callout"><b>A concrete example</b><p>${c.example}</p></div><h3>Ask yourself</h3><p>${c.check}</p><h3>Connect what you know</h3><p>${c.bridge}</p><div class="form-footer"><a class="btn secondary" href="#resource/${c.resource}">Read the primary source ↗</a><button class="btn primary" data-action="note-concept" data-id="${id}">Keep a note ${icon('note')}</button></div>`);}
function traceModal(){traceStep=0;showModal('A branch, one observation at a time',`<p>A simplified teaching trace of <code>classify(unsigned int value)</code>. Linux x86-64 System V context. Real compiler output may differ.</p><div class="trace-controls"><label class="form-field"><span>Choose an unsigned input</span><select id="trace-input"><option value="15">15 · below the boundary</option><option value="16">16 · at the boundary</option><option value="17">17 · above the boundary</option></select></label><button class="btn secondary" data-action="trace-reset">Reset</button></div><div id="trace-output"></div><div class="form-footer"><span id="trace-counter" class="muted"></span><button class="btn primary" data-action="trace-step">Step instruction ${icon('arrow')}</button></div><p class="small-note">An illustrative model, not a native execution engine. The unsigned branch uses CF: jae is taken when CF = 0 after cmp.</p>`,true);renderTrace();}
function renderTrace(){const input=Number($('#trace-input').value),take=input>=16;const lines=[['cmp edi, 0x10','Compare unsigned '+input+' with 16.'],['jae return_zero',take?'Branch taken: value ≥ 16.':'Branch not taken: value < 16.'],[take?'mov eax, 0':'mov eax, 1','Write the return value.'],['ret','Return '+(take?'0':'1')+' to the caller.']];$('#trace-output').innerHTML=`<div class="trace-registers"><div><span>edi · input</span><b>${input}</b></div><div><span>CF · after cmp</span><b>${traceStep>0?(take?'0':'1'):'—'}</b></div><div><span>eax · result</span><b>${traceStep>2?(take?'0':'1'):'—'}</b></div></div><div class="trace-lines">${lines.map(([c,d],i)=>`<div class="${i===traceStep?'current':i<traceStep?'executed':''}"><span>${String(i+1).padStart(2,'0')}</span><code>${c}</code><small>${i<traceStep?d:i===traceStep?'Next instruction':'Pending'}</small></div>`).join('')}</div>`;$('#trace-counter').textContent=traceStep===4?'Trace complete':traceStep+' / 4 executed';const b=$('[data-action="trace-step"]');b.disabled=traceStep===4;b.innerHTML=traceStep===4?'Trace complete '+icon('check'):'Step instruction '+icon('arrow');}
function searchModal(){showModal('Follow your curiosity',`<label class="global-search">${icon('search')}<input id="global-search" placeholder="Search concepts, labs, resources, notes…" autocomplete="off"></label><div id="search-results"><p class="muted">Try “memory”, “Ghidra”, “evidence”, or a note title.</p></div>`,true);}
function searchResults(q){q=q.trim().toLowerCase();const items=[...LABS.map(l=>({type:'Exercise',title:l.title,desc:l.objective,url:'#lab/'+l.id})),...RESOURCES.map(r=>({type:'Resource',title:r.name,desc:r.subtitle,url:'#resource/'+r.id})),...CONCEPTS.map(c=>({type:'Concept',title:c.title,desc:c.desc,action:'concept',id:c.id})),...state.notes.map(n=>({type:'Note',title:n.title,desc:n.body,action:'note-edit',id:n.id})),...PROJECTS.map(p=>({type:'Project idea',title:p.title,desc:p.desc,url:'#compare/projects'}))];const hits=q?items.filter(x=>(x.title+' '+x.desc).toLowerCase().includes(q)).slice(0,18):[];$('#search-results').innerHTML=!q?'<p class="muted">Try “memory”, “Ghidra”, “evidence”, or a note title.</p>':hits.length?hits.map(h=>`<${h.url?'a':'button'} class="search-result" ${h.url?'href="'+h.url+'"':'data-action="'+h.action+'" data-id="'+esc(h.id)+'"'}><span class="eyebrow">${h.type}</span><b>${esc(h.title)}</b><p>${esc(h.desc.slice(0,120))}</p></${h.url?'a':'button'}>`).join(''):'<div class="empty-state"><h3>No matches yet.</h3><p>Try a shorter search or a different term.</p></div>';}
function download(filename,content,type='text/plain'){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function projectMarkdown(p){return`# ${p.title}\n\nStatus: ${p.status}\nUpdated: ${p.date}\nVerification: self-attested; not independently reviewed.\n\n`+portfolioFields.map(([k,t])=>`## ${t}\n\n${p[k]||'Not recorded.'}\n`).join('\n');}
function confirmDelete(kind,id){const titles={note:'Delete this note?',portfolio:'Delete this project record?',session:'Remove this session?'};showModal(titles[kind],`<p>This removes the selected item from this browser’s workspace record.</p><div class="form-footer"><button class="btn secondary" data-action="close">Keep it</button><button class="btn danger-btn" data-action="delete-confirm" data-kind="${kind}" data-id="${esc(id)}">Delete item</button></div>`);}
let importCandidate=null;
document.addEventListener('click',async e=>{
 if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}
 const f=e.target.closest('[data-filter]');if(f){filters[f.dataset.filter]=f.dataset.value;render();return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 switch(a){
 case'menu':setMenu(!$('#sidebar').classList.contains('open'));break;
 case'close':closeModal();break;
 case'profile':profileModal();break;
 case'settings':settingsModal();break;
 case'search':searchModal();break;
 case'environment':environmentEditor();break;
 case'concept':conceptModal(id);break;
 case'note-new':noteEditor();break;
 case'note-template':noteEditor(null,id);break;
 case'note-edit':noteEditor(id);break;
 case'note-lab':noteEditor(null,null,id);break;
 case'note-concept':{const c=CONCEPTS.find(c=>c.id===id);noteEditor(null,'question');$('#note-form [name="title"]').value=c.title+' — questions';break;}
 case'session':sessionEditor(id);break;
 case'lab-complete':completionModal(id);break;
 case'completion-remove':delete state.completions[id];persist();closeModal();render();toast('Exercise marked as still exploring.');break;
 case'bookmark':state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();render();toast(state.bookmarks.includes(id)?'Saved to your resource shelf.':'Removed from saved resources.');break;
 case'source':{const l=lab(id);download(l.filename,l.source,'text/x-c');toast('Teaching source downloaded.');break;}
 case'handout':{const l=lab(id);download(l.id+'-guide.md',`# ${l.title}\n\n${l.objective}\n\nScope: educational, owned/authorized programs only. Run in your isolated lab.\n\n## Method\n\n`+l.steps.map((s,i)=>(i+1)+'. '+s).join('\n\n')+(l.commands?'\n\n## Lab commands\n\n```\n'+l.commands+'\n```':'')+'\n\n## Evidence\n\n'+l.evidence.map(s=>'- '+s).join('\n')+'\n\n## Learning output\n\n'+l.outcome+'\n\nResource: '+resource(l.resource).url);break;}
 case'copy-commands':try{await navigator.clipboard.writeText(lab(id).commands);toast('Commands copied. Run them in your lab VM.');}catch{toast('Clipboard unavailable. Select and copy the command text.');}break;
 case'portfolio-new':portfolioEditor();break;
 case'portfolio-edit':portfolioEditor(id);break;
 case'project-start':portfolioEditor(null,id);break;
 case'portfolio-export':{const p=state.portfolio.find(p=>p.id===id);download('binary-atlas-project-'+id.slice(0,8)+'.md',projectMarkdown(p),'text/markdown');break;}
 case'note-delete':confirmDelete('note',id);break;
 case'portfolio-delete':confirmDelete('portfolio',id);break;
 case'session-delete':confirmDelete('session',id);break;
 case'delete-confirm':{const k={note:'notes',portfolio:'portfolio',session:'sessions'}[b.dataset.kind];state[k]=state[k].filter(x=>x.id!==id);persist();closeModal();render();toast('Item deleted.');break;}
 case'export':download('binary-atlas-backup-'+today()+'.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Workspace backup downloaded.');break;
 case'import-confirm':if(importCandidate){state=importCandidate;persist();importCandidate=null;closeModal();render();toast('Workspace restored from the reviewed backup.');}break;
 case'trace':traceModal();break;
 case'trace-step':traceStep=Math.min(4,traceStep+1);renderTrace();break;
 case'trace-reset':traceStep=0;renderTrace();break;
 case'clear-labs':filters.labs='all';queries.labs='';render();break;
 case'clear-resources':filters.resources='all';queries.resources='';render();break;
 case'clear-concepts':filters.concepts='All';queries.concepts='';render();break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.dataset.query){const k=e.target.dataset.query,pos=e.target.selectionStart;queries[k]=e.target.value.toLowerCase();render();const inp=$('[data-query="'+k+'"]');inp?.focus();inp?.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{if(e.target.dataset.safety){state.safety[e.target.dataset.safety]=e.target.checked;persist();render();}if(e.target.dataset.selectFilter){filters[e.target.dataset.selectFilter]=e.target.value;render();}if(e.target.id==='trace-input'){traceStep=0;renderTrace();}if(e.target.dataset.compare){const id=e.target.dataset.compare,arr=compareSelection[compareType];if(e.target.checked&&arr.length>=3){e.target.checked=false;toast('Choose up to 3 items for a readable comparison.');return;}compareSelection[compareType]=e.target.checked?[...arr,id]:arr.filter(i=>i!==id);render();}if(e.target.id==='import-file'&&e.target.files[0]){const file=e.target.files[0];if(file.size>5e6){toast('Choose a backup smaller than 5 MB.');return;}try{importCandidate=validateState(JSON.parse(await file.text()));showModal('Review your workspace backup',`<p>This backup contains:</p><ul class="plain-list"><li>${Object.keys(importCandidate.completions).length} exercise completions</li><li>${importCandidate.notes.length} notes</li><li>${importCandidate.sessions.length} practice sessions</li><li>${importCandidate.portfolio.length} project records</li></ul><div class="callout"><b>Replace this browser’s current record?</b><p>Export the current workspace first if you want to keep it. This restores the selected backup rather than merging it.</p></div><div class="form-footer"><button class="btn secondary" data-action="export">Export current record</button><button class="btn secondary" data-action="close">Cancel</button><button class="btn primary" data-action="import-confirm">Restore backup</button></div>`);}catch(err){importCandidate=null;toast('Could not import: '+err.message);}}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.id)return;e.preventDefault();const f=Object.fromEntries(new FormData(form));const id=form.dataset.id;
 if(form.id==='note-form'){if(!f.title.trim()){toast('Add a note title.');return;}const n={id:id||uid(),title:f.title.trim(),body:f.body,tag:f.tag,updated:new Date().toISOString()};state.notes=id?state.notes.map(x=>x.id===id?n:x):[...state.notes,n];persist();closeModal();render();toast('Research note saved.');}
 if(form.id==='session-form'){const minutes=Number(f.minutes);if(!Number.isFinite(minutes)||minutes<1||minutes>1440||!f.takeaway.trim())return;const date=new Date(f.date+'T00:00:00+09:00');if(!Number.isFinite(date.getTime())||f.date>today()){toast('Choose today or an earlier date.');return;}state.sessions.push({id:uid(),lab:f.lab,minutes,takeaway:f.takeaway.trim(),date:date.toISOString()});persist();closeModal();render();toast('Practice session recorded.');}
 if(form.id==='completion-form'){if(!f.evidence.trim()){toast('Add your actual evidence reference.');return;}state.completions[id]={date:new Date().toISOString(),evidence:f.evidence.trim()};persist();closeModal();render();toast('Learning output recorded.');}
 if(form.id==='environment-form'){for(const k of Object.keys(state.env))state.env[k]=(f[k]||'').trim();persist();closeModal();render();toast('Environment baseline saved.');}
 if(form.id==='settings-form'){const v=Number(f.goal);if(v<15||v>1200){toast('Set a goal between 15 and 1200 minutes.');return;}state.goal=v;persist();closeModal();render();toast('Practice goal updated.');}
 if(form.id==='portfolio-form'){if(!f.title.trim())return;const verified=f.verified==='on';const missing=portfolioFields.filter(([k])=>!f[k]?.trim());if(verified&&missing.length){$('#portfolio-error').textContent='To self-verify, complete: '+missing.map(x=>x[1]).join(', ')+'. You can also save as a draft.';$('#portfolio-error').scrollIntoView({block:'nearest'});return;}const p={id:id||uid(),title:f.title.trim(),status:verified?'self-verified':'draft',date:new Date().toISOString()};for(const [k]of portfolioFields)p[k]=f[k].trim();state.portfolio=id?state.portfolio.map(x=>x.id===id?p:x):[...state.portfolio,p];persist();closeModal();render();toast(verified?'Project saved with your verification attestation.':'Project draft saved. Unknown details remain blank.');}
});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(e.key==='Escape'){closeModal();setMenu(false);}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();searchModal();}if(e.key==='Tab'&&modal){const nodes=$$('button,a,input,textarea,select,[tabindex="0"]',modal).filter(n=>!n.disabled&&n.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('.modal a[href^="#"]'))closeModal();});
render();
